/// Receiving controls `same_btree_keys` pays before its walk.
pub(super) fn same_btree_keys_control_bytes() -> usize {
    2 * std::mem::size_of::<Result<bool, Diagnostic>>()
        + 2 * std::mem::size_of::<Result<Option<&K>, Diagnostic>>()
        + 2 * std::mem::size_of::<Result<(), Diagnostic>>()
        + std::mem::size_of::<Iter<'_, K>>()
        + std::mem::size_of::<std::collections::btree_set::Iter<'_, K>>()
        + 4 * std::mem::size_of::<Option<&K>>()
        + 4 * std::mem::size_of::<&K>()
        + 2 * std::mem::size_of::<bool>()
}

/// Compare a retained full-key directory with one borrowed ordered set.
/// The set and directory retain all original identities; no second key set.
///
/// The walk debits no work. It replaces the original route's unmetered
/// `BTreeSet` equality (`structural_maps::validate_reference_coverage`),
/// and observable work must not depend on which route the payer selects
/// (d70e4af22 added this route with per-key step and comparison debits,
/// which refused programs the original route admitted). The walk is
/// linear in the already-bounded status count, exactly like the original.
pub(super) fn same_btree_keys(
    &self,
    other: &BTreeSet<K>,
    function: &ResolvedFunction,
    budget: &mut ReplayBudget,
) -> Result<bool, Diagnostic> {
    self.authenticate(function, budget)?;
    budget.reserve_bytes(
        function,
        Self::same_btree_keys_control_bytes(),
        "retained reference comparison controls",
    )?;
    if self.len() != other.len() {
        return Ok(false);
    }
    let mut left = self.iter();
    for right in other {
        let Some(key) = left.next() else {
            return Ok(false);
        };
        if Ord::cmp(key, right) != Ordering::Equal {
            return Ok(false);
        }
    }
    Ok(true)

    budget.reserve_bytes(
        function,
        2 * std::mem::size_of::<(u8, bool)>()
            + 2 * std::mem::size_of::<(&mut ReplayBudget, &ResolvedFunction, usize, &str)>()
            + 2 * std::mem::size_of::<Result<(), Diagnostic>>(),
        "directory height-stable insertion controls",
    )?;
    while at != NIL {
        budget.charge(function, REBALANCE_UNITS + 3, self.phase)?;
        let previous_height = self.nodes[at].height;
        self.update(at, function, budget)?;
        let (left, right) = (self.nodes[at].left, self.nodes[at].right);
        let top = if i16::from(self.height(left)) - i16::from(self.height(right)) > 1 {
            if self.height(self.nodes[left].left) < self.height(self.nodes[left].right) {
                self.rotate_left(left, function, budget)?;
            }
            self.rotate_right(at, function, budget)?
        } else if i16::from(self.height(right)) - i16::from(self.height(left)) > 1 {
            if self.height(self.nodes[right].right) < self.height(self.nodes[right].left) {
                self.rotate_right(right, function, budget)?;
            }
            self.rotate_left(at, function, budget)?
        } else {
            at
        };
        // A balanced insertion stops propagating as soon as the repaired
        // subtree keeps its old height; higher ancestors remain unchanged.
        if self.nodes[top].height == previous_height {
            break;
        }
        at = self.nodes[top].parent;
    }
    Ok(())
}
